  /** 抽出された課題リスト（優先度付き） */
  prioritizedIssues: Array<{
    issueId: string;
    title: string;
    description: string;
    priority: "critical" | "high" | "medium" | "low";
    affectedMembers: string[];
    recommendedAction: string;
  }>;
  /** 日報提出状況サマリー */
  submissionSummary: {
    totalMembers: number;
    submittedCount: number;
    pendingCount: number;
    lateCount: number;
  };
  /** 朝会開始予定時刻 */
