/**
 * Action 6 プロンプトを構築する
 * 
 * 整理済みの進捗レポートと課題優先度リストを部長に提示するための
 * AIプロンプトを生成し、構造化された出力を期待する
 * 
 * @param input - プロンプト生成に必要な入力情報
 * @returns 部長向けレポート生成用のプロンプト文字列
 */
export function buildAction06Prompt(input: Action06PromptInput): string {
  const {
    managerName,
    departmentName,
    aggregatedProgress,
    prioritizedIssues,
    submissionSummary,
    meetingStartTime,
    generatedAt,
  } = input;

  const issuesSectionMarkdown = prioritizedIssues
    .map((issue) => {
      const priorityEmoji = {
        critical: "🔴",
        high: "🟠",
        medium: "🟡",
        low: "🟢",
      }[issue.priority];

      return `${priorityEmoji} **[${issue.priority.toUpperCase()}] ${issue.title}**
  - ID: ${issue.issueId}
  - 説明: ${issue.description}
  - 影響範囲: ${issue.affectedMembers.join(", ")}
  - 推奨アクション: ${issue.recommendedAction}`;
    })
    .join("\n\n");

  const submissionStatusMarkdown = `
- 総人数: ${submissionSummary.totalMembers}
- 提出済み: ${submissionSummary.submittedCount}
- 未提出: ${submissionSummary.pendingCount}
- 遅延: ${submissionSummary.lateCount}
`;

  const prompt = `# 朝会準備レポート生成指示

## 対象情報
- 部長: ${managerName}
- 部門: ${departmentName}
- 朝会開始予定時刻: ${meetingStartTime}
- レポート生成時刻: ${generatedAt}

## 日報提出状況
${submissionStatusMarkdown}

## 全体進捗状況（集約済み）
${aggregatedProgress}

## 抽出された課題・ボトルネック（優先度順）
${issuesSectionMarkdown}

## 指示

以下の形式で、部長向けの朝会準備レポートを生成してください。

### 1. レポート本文の作成
- 日報提出状況の簡潔なサマリー
- 全体進捗の主要ポイント
- 本日の重点課題
- 推奨される対応方針

### 2. 課題優先度リストの整理
- 優先度別に課題を分類
- 各課題の影響範囲と緊急度を明記
- 推奨アクションを具体的に記述

### 3. 朝会アジェンダの提案
- 優先度に基づいた議論順序
- 各議題の推定所要時間
- 決定が必要な項目の明示

### 4. 即座の対応判定
- 朝会開始前に対応が必要な重大課題の有無を判定
- 必要に応じて事前通知の推奨

### 5. 追加確認項目の抽出
- 部長による最終確認が必要な項目
- 通常と異なる事象や例外ケース

## 出力形式

JSON形式で以下の構造で返してください：
\`\`\`json
{
  "reportContent": "部長向けレポートの本文（マークダウン形式）",
  "priorityListFormatted": "課題優先度リスト（マークダウン形式）",
  "suggestedAgenda": ["アジェンダ項目1", "アジェンダ項目2", ...],
  "hasUrgentIssues": true/false,
  "itemsRequiringReview": ["確認項目1", "確認項目2", ...]
}
\`\`\`

## 品質基準
- 情報は正確かつ簡潔に
- 優先度判定は客観的根拠に基づく
- 推奨アクションは実行可能な具体性を持つ
- 部長が朝会3分前に読んで理解できる分量
`;

  return prompt;
}
